INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'al-manar-films-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Al-Manar Films in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من أفلام المنار في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Full-service cinema production house delivering feature documentaries, brand films, and broadcast commercials across the Gulf. Focusing on Cinema DCP Mastering & Subtitling, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"دار إنتاج سينمائي متكاملة تقدم الأفلام الوثائقية والأفلام الإعلانية والتجارية في منطقة الخليج. من خلال خدمة تجهيز نسخ العرض السينمائي والترجمة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Full-service cinema production house delivering feature documentaries, brand films, and broadcast commercials across the Gulf.</p><p>Focusing on <strong>Cinema DCP Mastering & Subtitling</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>دار إنتاج سينمائي متكاملة تقدم الأفلام الوثائقية والأفلام الإعلانية والتجارية في منطقة الخليج.</p><p>من خلال خدمة <strong>تجهيز نسخ العرض السينمائي والترجمة</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Al-Manar Films', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | أفلام المنار', 'Executive guide by Al-Manar Films covering Cinema DCP Mastering & Subtitling benchmarks in Bahrain.', 'دليل تنفيذي من أفلام المنار حول معايير تجهيز نسخ العرض السينمائي والترجمة في البحرين.', 'Sustainability', '{"media","sustainability","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
